<?php
/**
 * Compatibility-preserving controller action seam. The ePaper front controller
 * retains route dispatch; actions are composed into it until typed controllers
 * can be introduced behind the same route contract.
 */
namespace EpaperSaas\Controllers;
use EpaperSaas\Core\{Auth,Build,Config,Http,RateLimiter,RedisStore,RequestContext,Store,Uuid,View};
use EpaperSaas\Services\{AnalyticsCatalog,Audit,CacheInspector,ClipService,DomainResolver,DirectRecovery,EditionOperations,EditionManifest,Entitlements,InfrastructureConfig,Media,DesktopAuth,DeviceAuth,MobileAuth,MobileAuthPendingException,MultiLayerCache,OfflineVault,PlatformClient,Processing,ProcessingRecovery,ProductionReadiness,PublicReadCache,PublishingRuntime,PublishingScheduler,QueueService,RecoveryCenter,RabbitMq,ReaderNavigation,ReaderSession,RuntimeCache,SchemaDoctor,SemanticNews,SeoDiscovery,SettingsCatalog,SupervisorRuntime,TenantData,TrustedAppAuth,PerformanceTelemetry};

trait AccountActions
{
    private function publicSubscribe(): never
    {
        $u=Auth::user();if($u)Http::redirect('/account/subscription');
        $return='/account/subscription';$login='/login?return='.rawurlencode($return);
        $h='<section class="subscription-public"><div class="subscription-public-card"><span class="eyebrow">EPAPER ACCESS</span><h1>Continue your clipping experience</h1><p>Sign in to view the subscription and entitlement options available for this publication. Your account remains on this ePaper domain while subscription status is synchronized securely in the background.</p><div class="subscription-feature-grid"><div><strong>Clippings</strong><span>Create and keep visual newspaper clips.</span></div><div><strong>Library</strong><span>Access saved clips and bookmarks across devices.</span></div><div><strong>Offline</strong><span>Use offline editions when included in your plan.</span></div></div><div class="subscription-public-actions"><a class="btn primary" href="'.$this->e($login).'">Sign in / Create account</a><a class="btn ghost" href="/">Back to ePaper</a></div></div></section>';
        View::layout('Subscription options',$h,['brand'=>$this->brandName()]);
    }

    private function accountSubscription(array $u): never
    {
        try{$access=PlatformClient::instance()->access(RequestContext::tenantGuid());}catch(\Throwable$e){$access=['service_access_state'=>'UNKNOWN','subscription'=>null,'error'=>$e->getMessage()];}
        $ents=Entitlements::all();$sub=is_array($access['subscription']??null)?$access['subscription']:[];$status=(string)($sub['status']??($access['service_access_state']??'UNKNOWN'));$plan=(string)($sub['plan_name']??$sub['product_name']??$sub['price_name']??'Current ePaper access');$period=(string)($sub['current_period_end']??$sub['period_end']??'');
        $clip=Entitlements::has('EPAPER.CLIPPING',true);$offline=Entitlements::has('EPAPER.OFFLINE',true);
        $h='<section class="page-head account-page-head"><div><span class="eyebrow">SUBSCRIPTION</span><h1>Subscription & access</h1><p class="muted">Your ePaper account stays on this domain. Commercial status and entitlements are synchronized securely in the background.</p></div><a class="btn ghost" href="/account">Back to Library</a></section>';
        $h.='<div class="kpis subscription-kpis"><div class="kpi"><span>Access</span><strong style="font-size:20px">'.$this->e($status).'</strong></div><div class="kpi"><span>Plan</span><strong style="font-size:20px">'.$this->e($plan).'</strong></div><div class="kpi"><span>Clipping</span><strong style="font-size:20px">'.($clip?'Included':'Not included').'</strong></div><div class="kpi"><span>Offline</span><strong style="font-size:20px">'.($offline?'Included':'Not included').'</strong></div></div>';
        if($period!=='')$h.='<div class="alert info">Current access period ends <strong>'.$this->e($period).'</strong>.</div>';
        if(!$clip)$h.='<section class="panel subscription-attention"><span class="eyebrow">CLIPPING</span><h2>Clipping is not included in the current access</h2><p class="muted">Contact your publisher/account administrator to enable clipping for this account. No separate Platform login is required.</p></section>';
        $h.='<section class="panel"><h2>Effective ePaper access</h2><div class="table-wrap"><table><thead><tr><th>Feature</th><th>Value</th></tr></thead><tbody>';foreach($ents as$k=>$v)$h.='<tr><td><code>'.$this->e($k).'</code></td><td>'.$this->e(is_scalar($v)?$v:json_encode($v)).'</td></tr>';$h.='</tbody></table></div></section>';
        View::layout('Subscription',$h,['brand'=>$this->brandName(),'account'=>true]);
    }

    private function runAccount(string $path,string $method): never
    {
        $u=Auth::requireUser();RequestContext::set(RequestContext::all()+['user_guid'=>$u['user_guid']]);if($method==='POST')Http::verifyCsrf();
        if($path==='/account/subscription')$this->accountSubscription($u);
        if($path==='/account/library')$this->accountLibrary($u);
        if($path==='/account/devices')$this->accountDevices($u);
        if($method==='POST'&&preg_match('#^/account/devices/([0-9a-f-]{36})/revoke$#i',$path,$m))$this->accountDeviceRevoke($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/(saved-articles|bookmarks|clips|history|offline|notifications)/clear$#',$path,$m))$this->accountClear($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/saved-articles/([0-9a-f-]{36})/(update|delete)$#i',$path,$m))$this->accountSavedAction($u,$m[1],$m[2]);
        if($method==='POST'&&preg_match('#^/account/bookmarks/([0-9a-f-]{36})/(update|delete)$#i',$path,$m))$this->accountBookmarkAction($u,$m[1],$m[2]);
        if($method==='POST'&&preg_match('#^/account/clips/([A-Za-z0-9_-]+)/(update|delete)$#',$path,$m))$this->accountClipAction($u,$m[1],$m[2]);
        if($method==='POST'&&preg_match('#^/account/history/([0-9a-f-]{36})/delete$#i',$path,$m))$this->accountHistoryDelete($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/offline/([0-9a-f-]{36})/delete$#i',$path,$m))$this->accountOfflineDelete($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/notifications/([0-9a-f-]{36})/(read|delete)$#i',$path,$m))$this->accountNotificationAction($u,$m[1],$m[2]);
        if($path==='/account')$this->accountOverview($u);
        $map=['/account/saved-articles'=>'saved','/account/bookmarks'=>'bookmarks','/account/clips'=>'clips','/account/history'=>'history','/account/offline'=>'offline','/account/notifications'=>'notifications'];if(isset($map[$path]))$this->accountList($u,$map[$path]);http_response_code(404);View::layout('Not Found','<section class="empty-state"><h1>Account page not found</h1></section>',['brand'=>$this->brandName(),'account'=>true]);
    }

    private function accountOverview(array $u): never
    {
        $uid=Uuid::toBinary($u['user_guid']);OfflineVault::expireOld($uid);$metrics=$this->accountOverviewMetrics($uid,(string)$u['user_guid']);
        $resume=Store::one('SELECT h.page_number,h.last_viewed_at,e.edition_guid,e.slug,e.edition_date,e.page_count,e.title,p.name publication_name,a.asset_guid thumb_asset_guid FROM ep_history h JOIN ep_editions e ON e.tenant_guid=h.tenant_guid AND e.edition_guid=h.edition_guid JOIN ep_publications p ON p.tenant_guid=e.tenant_guid AND p.publication_guid=e.publication_guid LEFT JOIN ep_pages pg ON pg.tenant_guid=h.tenant_guid AND pg.edition_guid=h.edition_guid AND pg.page_number=h.page_number LEFT JOIN ep_page_assets a ON a.tenant_guid=pg.tenant_guid AND a.page_guid=pg.page_guid AND a.asset_type="THUMB" WHERE h.tenant_guid=? AND h.platform_user_guid=? ORDER BY h.last_viewed_at DESC LIMIT 1',[TenantData::tenantBin(),$uid]);
        $html='<section class="reader-os-hero"><div><span class="eyebrow">READER OS · '.OfflineVault::VERSION.'</span><h1>Reader OS</h1><p>Your reading, saved content, encrypted offline editions, notifications and preferences in one place.</p></div><div class="reader-os-hero-actions"><button class="btn ghost hidden" type="button" data-pwa-install>Install app</button><span class="reader-os-version">v2.0</span></div></section>';
        if($resume){$page=max(1,(int)$resume['page_number']);$total=max(1,(int)$resume['page_count']);$img=$this->assetUrlFromBinary($resume['thumb_asset_guid']??null);$html.='<section class="continue-reading-feature"><div class="continue-cover">'.($img?'<img src="'.$this->e($img).'" alt="" loading="eager" decoding="async">':'').'</div><div class="continue-copy"><span class="eyebrow">CONTINUE READING</span><h2>'.$this->e($resume['title']?:$resume['publication_name'].' · '.date('d M Y',strtotime($resume['edition_date']))).'</h2><p>Page '.$page.' of '.$total.' · Last read '.date('d M, H:i',strtotime($resume['last_viewed_at'])).'</p></div><a class="btn primary" href="/edition/'.$this->e($resume['slug']).'/page/'.$page.'">Continue →</a></section>';}
        else $html.='<section class="continue-reading-feature empty"><div class="continue-copy"><span class="eyebrow">START READING</span><h2>Your latest edition is ready</h2><p>Open an edition and Reader OS will remember where you stopped.</p></div><a class="btn primary" href="/">Read latest →</a></section>';
        $stats=[['Bookmarks',(int)$metrics['bookmarks'],'/account/bookmarks'],['Saved articles',(int)$metrics['saved_articles'],'/account/saved-articles'],['Clippings',(int)$metrics['clips'],'/account/clips'],['Offline editions',(int)$metrics['offline'],'/account/offline'],['Unread alerts',(int)$metrics['notifications'],'/account/notifications']];$html.='<div class="reader-os-stats">';foreach($stats as[$label,$value,$href])$html.='<a href="'.$href.'"><strong>'.$value.'</strong><span>'.$this->e($label).'</span></a>';$html.='</div>';
        $cap=[['Smart Discovery',true],['Smart Article',Entitlements::has('EPAPER.ARTICLE_MODE',false)],['OCR Search',Entitlements::has('EPAPER.OCR_SEARCH',false)],['Cross-device Resume',true],['Bookmarks',true],['Clipping',Entitlements::has('EPAPER.CLIPPING',true)],['Offline Editions',Entitlements::has('EPAPER.OFFLINE',true)],['Personalization',true],['Listen / TTS',Entitlements::has('EPAPER.TTS',false)],['Translation',Entitlements::has('EPAPER.TRANSLATION',false)]];
        $html.='<div class="reader-os-grid"><section class="reader-os-panel"><div class="section-head"><div><span class="eyebrow">YOUR READER</span><h2>Capabilities</h2></div><a href="/account/subscription">Manage plan</a></div><div class="capability-grid">';foreach($cap as[$label,$enabled])$html.='<div class="capability '.($enabled?'enabled':'disabled').'"><span class="capability-mark">'.($enabled?'✓':'—').'</span><div><strong>'.$this->e($label).'</strong><small>'.($enabled?'Available':'Not in current plan').'</small></div></div>';$html.='</div></section>';
        $recent=Store::all('SELECT h.page_number,h.last_viewed_at,e.slug,e.edition_date,e.title,p.name publication_name FROM ep_history h JOIN ep_editions e ON e.tenant_guid=h.tenant_guid AND e.edition_guid=h.edition_guid JOIN ep_publications p ON p.tenant_guid=e.tenant_guid AND p.publication_guid=e.publication_guid WHERE h.tenant_guid=? AND h.platform_user_guid=? ORDER BY h.last_viewed_at DESC LIMIT 5',[TenantData::tenantBin(),$uid]);$html.='<section class="reader-os-panel"><div class="section-head"><div><span class="eyebrow">RECENT</span><h2>Reading history</h2></div><a href="/account/history">View all</a></div><div class="reader-history-list">';if($recent){foreach($recent as$r)$html.='<a href="/edition/'.$this->e($r['slug']).'/page/'.max(1,(int)$r['page_number']).'"><strong>'.$this->e($r['title']?:$r['publication_name']).'</strong><span>'.$this->e(date('d M Y',strtotime($r['edition_date']))).' · Page '.max(1,(int)$r['page_number']).'</span></a>';}else$html.='<p class="muted">No recent reading yet.</p>';$html.='</div></section></div>';
        View::layout('Reader OS',$html,['brand'=>$this->brandName(),'account'=>true]);
