    {
        $uid=Uuid::toBinary($u['user_guid']);$m=$this->accountOverviewMetrics($uid,(string)$u['user_guid']);$html='<section class="page-head account-page-head"><div><span class="eyebrow">MY EPAPER</span><h1>Library</h1><p class="muted">Saved stories, bookmarked pages, clippings, reading history and encrypted offline editions in one visual library.</p></div><div class="page-head-actions"><a class="btn ghost" href="/archive">Browse archive</a><a class="btn primary" href="/">Read latest</a></div></section><nav class="library-tabs" aria-label="Library categories"><a class="active" href="/account/library">Library</a><a href="/account/saved-articles">Saved Articles</a><a href="/account/bookmarks">Bookmarks</a><a href="/account/clips">Clips</a><a href="/account/history">History</a><a href="/account/offline">Offline</a><a href="/account/notifications">Notifications</a></nav>';
