    private function accountDevices(array $u): never
    {
        $devices=OfflineVault::devices($u);$html='<section class="page-head account-page-head"><div><span class="eyebrow">SECURITY</span><h1>Devices</h1><p class="muted">Manage browsers and installed PWAs authorized to hold encrypted offline editions.</p></div><a class="btn ghost" href="/account/offline">Offline Library</a></section><section class="reader-os-panel"><div class="section-head"><div><span class="eyebrow">OFFLINE VAULT</span><h2>Authorized devices</h2></div><span class="pill">'.count($devices).' devices</span></div><div class="device-list">';if(!$devices)$html.='<p class="muted">No offline devices registered yet. Saving an edition offline will register this browser automatically.</p>';else foreach($devices as$d){$guid=(string)$d['device_guid'];$html.='<article class="device-row" data-device-guid="'.$this->e($guid).'"><div><strong>'.$this->e($d['label']).'</strong><span>'.strtoupper($this->e($d['status'])).' · '.(int)$d['offline_editions'].' offline editions</span><small>Last seen '.($d['last_seen_at']?date('d M Y · H:i',strtotime($d['last_seen_at'])):'—').'</small></div>'.(strtoupper((string)$d['status'])==='ACTIVE'?'<form method="post" action="/account/devices/'.$this->e($guid).'/revoke" data-vault-device-revoke="'.$this->e($guid).'" data-confirm="Revoke this offline device? Downloaded editions on that device will stop at expiry or next sync.">'.$this->csrf().'<button class="btn ghost danger">Revoke</button></form>':'<span class="pill danger">Revoked</span>').'</article>';}$html.='</div></section>';
        View::layout('Devices',$html,['brand'=>$this->brandName(),'account'=>true]);
    }

    private function accountDeviceRevoke(array $u,string $deviceGuid): never
    {
        OfflineVault::revokeDevice($u,$deviceGuid);Audit::log('offline.device.revoked','offline_device',$deviceGuid);Http::redirect('/account/devices?updated=1');
    }

    private function accountOverviewMetrics(string $uidBin,string $userGuid): array
    {
        $key='account:overview:v2:'.RequestContext::tenantGuid().':'.$userGuid;
        $cached=RedisStore::getJson($key);
        if(is_array($cached))return $cached;
        $tb=TenantData::tenantBin();
        $row=Store::one('SELECT
            (SELECT COUNT(*) FROM ep_saved_articles WHERE tenant_guid=? AND platform_user_guid=?) AS saved_articles,
            (SELECT COUNT(*) FROM ep_bookmarks WHERE tenant_guid=? AND platform_user_guid=?) AS bookmarks,
            (SELECT COUNT(*) FROM ep_clips WHERE tenant_guid=? AND platform_user_guid=?) AS clips,
            (SELECT COUNT(*) FROM ep_history WHERE tenant_guid=? AND platform_user_guid=?) AS history,
            (SELECT COUNT(DISTINCT edition_guid) FROM ep_offline_items WHERE tenant_guid=? AND platform_user_guid=? AND status="READY" AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP(6))) AS offline,
            (SELECT COUNT(*) FROM ep_notifications WHERE tenant_guid=? AND (platform_user_guid=? OR platform_user_guid IS NULL) AND status="UNREAD") AS notifications',[$tb,$uidBin,$tb,$uidBin,$tb,$uidBin,$tb,$uidBin,$tb,$uidBin,$tb,$uidBin])?:[];
        $metrics=[
            'saved_articles'=>(int)($row['saved_articles']??0),
            'bookmarks'=>(int)($row['bookmarks']??0),
            'clips'=>(int)($row['clips']??0),
            'history'=>(int)($row['history']??0),
            'offline'=>(int)($row['offline']??0),
            'notifications'=>(int)($row['notifications']??0),
        ];
        RedisStore::setJson($key,$metrics,RedisStore::ttlWithJitter(10,2));
        return $metrics;
    }

    private function assetUrlFromBinary(mixed $assetGuid,int $ttl=3600): ?string
    {
        if(!is_string($assetGuid)||$assetGuid==='')return null;
        try{$guid=Uuid::fromBinary($assetGuid);}catch(\Throwable){return null;}
        return $guid?'/media/'.Media::token($guid,$ttl):null;
    }

    private function accountList(array $u,string $type): never
    {
        $uid=Uuid::toBinary($u['user_guid']);$labels=['saved'=>'Saved Articles','bookmarks'=>'Bookmarks','clips'=>'Clips','history'=>'History','offline'=>'Offline','notifications'=>'Notifications'];$paths=['saved'=>'saved-articles','bookmarks'=>'bookmarks','clips'=>'clips','history'=>'history','offline'=>'offline','notifications'=>'notifications'];$title=$labels[$type]??ucwords(str_replace('-',' ',$type));$descriptions=['saved'=>'Stories saved from Smart Article mode.','bookmarks'=>'Newspaper pages you marked for quick return.','clips'=>'Your visual clipping gallery.','history'=>'Your recent reading activity, newest first.','offline'=>'Editions saved for offline reading.','notifications'=>'Edition, account and application updates.'];$clearPath=$paths[$type]??$type;$removableCount=$this->accountRemovableCount($uid,$type);$clearForm=$removableCount>0?'<form method="post" action="/account/'.$this->e($clearPath).'/clear" data-confirm="Clear all removable '.$this->e(strtolower($title)).' from your account?">'.$this->csrf().'<button class="btn ghost danger">Clear all</button></form>':'';$success=!empty($_GET['cleared'])?'<div class="alert success account-action-result">'.(int)($_GET['count']??0).' '.$this->e(strtolower($title)).' cleared.</div>':'';$html='<section class="page-head account-page-head"><div><span class="eyebrow">LIBRARY</span><h1>'.$this->e($title).'</h1><p class="muted">'.$this->e($descriptions[$type]??'Your ePaper library.').'</p></div><div class="page-head-actions"><a class="btn ghost" href="/">Open ePaper</a>'.$clearForm.'</div></section>'.$success;$count=0;
        if($type==='notifications'){$rows=TenantData::toGuidRows(Store::all('SELECT notification_guid,platform_user_guid,title,body,target_url,status,created_at FROM ep_notifications WHERE tenant_guid=? AND (platform_user_guid=? OR platform_user_guid IS NULL) ORDER BY created_at DESC LIMIT 100',[TenantData::tenantBin(),$uid]),['notification_guid','platform_user_guid']);$html.='<div class="notification-feed">';foreach($rows as$r){$count++;$global=empty($r['platform_user_guid']);$html.='<article class="notification-row'.(strtoupper((string)$r['status'])==='UNREAD'?' unread':'').'"><span class="notification-dot" aria-hidden="true"></span><div><strong>'.$this->e($r['title']).'</strong>'.(!empty($r['body'])?'<p>'.$this->e($r['body']).'</p>':'').'<small>'.$this->e(date('d M Y · H:i',strtotime($r['created_at']))).($global?' · Publisher notification':'').'</small></div><div class="library-row-actions">'.(!$global&&strtoupper((string)$r['status'])==='UNREAD'?'<form method="post" action="/account/notifications/'.$r['notification_guid'].'/read">'.$this->csrf().'<button class="text-btn">Mark read</button></form>':'').(!$global?'<form method="post" action="/account/notifications/'.$r['notification_guid'].'/delete" data-confirm="Delete this notification?">'.$this->csrf().'<button class="text-btn danger">Delete</button></form>':'<span class="pill">Shared</span>').'</div></article>';}$html.='</div>';}
        else{$html.='<div class="library-grid visual-library-grid">';
            if($type==='saved'){$rows=Store::all('SELECT s.page_guid,s.title,s.text_snapshot,s.created_at,p.page_number,e.edition_guid,e.slug,e.edition_date,pub.name publication_name,a.asset_guid thumb_asset_guid FROM ep_saved_articles s JOIN ep_pages p ON p.tenant_guid=s.tenant_guid AND p.page_guid=s.page_guid JOIN ep_editions e ON e.tenant_guid=p.tenant_guid AND e.edition_guid=p.edition_guid JOIN ep_publications pub ON pub.tenant_guid=e.tenant_guid AND pub.publication_guid=e.publication_guid LEFT JOIN ep_page_assets a ON a.tenant_guid=p.tenant_guid AND a.page_guid=p.page_guid AND a.asset_type="THUMB" WHERE s.tenant_guid=? AND s.platform_user_guid=? ORDER BY s.created_at DESC LIMIT 100',[TenantData::tenantBin(),$uid]);foreach($rows as$r){$count++;$pageGuid=Uuid::fromBinary($r['page_guid']);$eg=Uuid::fromBinary($r['edition_guid']);$page=(int)$r['page_number'];$img=$this->assetUrlFromBinary($r['thumb_asset_guid']??null);$snippet=mb_substr(trim(preg_replace('/\s+/u',' ',(string)$r['text_snapshot'])),0,145);$manage='<form method="post" action="/account/saved-articles/'.$pageGuid.'/update" class="record-form">'.$this->csrf().'<label>Title<input name="title" value="'.$this->e($r['title']?:$r['publication_name']).'" maxlength="180"></label><button class="btn small">Save title</button></form><form method="post" action="/account/saved-articles/'.$pageGuid.'/delete" data-confirm="Remove this saved article?">'.$this->csrf().'<button class="record-action danger">Remove</button></form>';$html.=$this->accountCard('/edition/'.$this->e($r['slug']).'/page/'.$page,$img,'Page '.$page,'SAVED ARTICLE',$r['title']?:$r['publication_name'],$r['publication_name'].' · '.date('d M Y',strtotime($r['edition_date'])),$snippet?$snippet.'…':'',$manage);}}
            elseif($type==='bookmarks'){$rows=Store::all('SELECT b.target_guid,b.bookmark_type,b.note,b.created_at,p.page_number,e.edition_guid,e.slug,e.edition_date,pub.name publication_name,a.asset_guid thumb_asset_guid FROM ep_bookmarks b LEFT JOIN ep_pages p ON UPPER(b.bookmark_type)="PAGE" AND p.tenant_guid=b.tenant_guid AND p.page_guid=b.target_guid LEFT JOIN ep_editions e ON e.tenant_guid=p.tenant_guid AND e.edition_guid=p.edition_guid LEFT JOIN ep_publications pub ON pub.tenant_guid=e.tenant_guid AND pub.publication_guid=e.publication_guid LEFT JOIN ep_page_assets a ON a.tenant_guid=p.tenant_guid AND a.page_guid=p.page_guid AND a.asset_type="THUMB" WHERE b.tenant_guid=? AND b.platform_user_guid=? ORDER BY b.created_at DESC LIMIT 100',[TenantData::tenantBin(),$uid]);foreach($rows as$r){$count++;$target=Uuid::fromBinary($r['target_guid']);$eg=$r['edition_guid']?Uuid::fromBinary($r['edition_guid']):null;$page=(int)($r['page_number']??0);$img=$this->assetUrlFromBinary($r['thumb_asset_guid']??null);$url=!empty($r['slug'])?'/edition/'.$this->e($r['slug']).'/page/'.$page:'#';$manage='<form method="post" action="/account/bookmarks/'.$target.'/update" class="record-form">'.$this->csrf().'<label>Note<textarea name="note" rows="3" maxlength="500">'.$this->e($r['note']??'').'</textarea></label><button class="btn small">Save note</button></form><form method="post" action="/account/bookmarks/'.$target.'/delete" data-confirm="Remove this bookmark?">'.$this->csrf().'<button class="record-action danger">Remove</button></form>';$html.=$this->accountCard($url,$img,$page?'Page '.$page:'Bookmark','BOOKMARK',$r['publication_name']?:ucfirst((string)$r['bookmark_type']),!empty($r['edition_date'])?date('d M Y',strtotime($r['edition_date'])):date('d M Y',strtotime($r['created_at'])),$r['note']??'',$manage);}}
            elseif($type==='clips'){$rows=Store::all('SELECT c.clip_slug,c.title,c.visibility,c.created_at,c.view_count,p.page_number,e.slug edition_slug,e.edition_date,pub.name publication_name FROM ep_clips c JOIN ep_pages p ON p.tenant_guid=c.tenant_guid AND p.page_guid=c.page_guid JOIN ep_editions e ON e.tenant_guid=p.tenant_guid AND e.edition_guid=p.edition_guid JOIN ep_publications pub ON pub.tenant_guid=e.tenant_guid AND pub.publication_guid=e.publication_guid WHERE c.tenant_guid=? AND c.platform_user_guid=? ORDER BY c.created_at DESC LIMIT 100',[TenantData::tenantBin(),$uid]);foreach($rows as$r){$count++;$visibility=in_array(strtoupper((string)$r['visibility']),['PRIVATE','PUBLIC'],true)?strtoupper((string)$r['visibility']):'PRIVATE';$manage='<form method="post" action="/account/clips/'.$this->e($r['clip_slug']).'/update" class="record-form">'.$this->csrf().'<label>Title<input name="title" value="'.$this->e($r['title']?:'News clipping').'" maxlength="180" required></label><label>Visibility<select name="visibility"><option value="PRIVATE"'.($visibility==='PRIVATE'?' selected':'').'>Private</option><option value="PUBLIC"'.($visibility==='PUBLIC'?' selected':'').'>Public</option></select></label><button class="btn small">Save clipping</button></form><form method="post" action="/account/clips/'.$this->e($r['clip_slug']).'/delete" data-confirm="Delete this clipping and its generated share files permanently?">'.$this->csrf().'<button class="record-action danger">Delete clipping</button></form>';$html.=$this->accountCard('/c/'.$this->e($r['clip_slug']),'/c/'.$this->e($r['clip_slug']).'/image.webp','Page '.(int)$r['page_number'],'CLIPPING',$r['title']?:'Saved clipping',$r['publication_name'].' · '.date('d M Y',strtotime($r['edition_date'])),(int)$r['view_count'].' views · '.$visibility,$manage,'clip-media');}}
            elseif($type==='history'){$rows=Store::all('SELECT h.edition_guid,h.page_number,h.last_viewed_at,e.slug,e.title,e.edition_date,e.page_count,p.name publication_name,a.asset_guid thumb_asset_guid FROM ep_history h JOIN ep_editions e ON e.tenant_guid=h.tenant_guid AND e.edition_guid=h.edition_guid JOIN ep_publications p ON p.tenant_guid=e.tenant_guid AND p.publication_guid=e.publication_guid LEFT JOIN ep_pages pg ON pg.tenant_guid=h.tenant_guid AND pg.edition_guid=h.edition_guid AND pg.page_number=h.page_number LEFT JOIN ep_page_assets a ON a.tenant_guid=pg.tenant_guid AND a.page_guid=pg.page_guid AND a.asset_type="THUMB" WHERE h.tenant_guid=? AND h.platform_user_guid=? ORDER BY h.last_viewed_at DESC LIMIT 100',[TenantData::tenantBin(),$uid]);foreach($rows as$r){$count++;$eg=Uuid::fromBinary($r['edition_guid']);$page=(int)$r['page_number'];$img=$this->assetUrlFromBinary($r['thumb_asset_guid']??null);$manage='<form method="post" action="/account/history/'.$eg.'/delete" data-confirm="Remove this edition from reading history?">'.$this->csrf().'<button class="record-action danger">Remove from history</button></form>';$html.=$this->accountCard('/edition/'.$this->e($r['slug']).'/page/'.$page,$img,'Page '.$page,strtoupper(date('D',strtotime($r['last_viewed_at']))),$r['publication_name'],date('d M Y',strtotime($r['edition_date'])).' · Page '.$page.' of '.max(1,(int)$r['page_count']),'Viewed '.date('H:i',strtotime($r['last_viewed_at'])),$manage);}}
            elseif($type==='offline'){$rows=Store::all('SELECT o.edition_guid,o.license_guid,o.device_guid,o.status,o.byte_size,o.expires_at,o.page_count offline_page_count,o.downloaded_pages,o.updated_at,e.slug,e.edition_date,e.page_count,p.name publication_name,d.label device_label,a.asset_guid thumb_asset_guid FROM ep_offline_items o JOIN ep_editions e ON e.tenant_guid=o.tenant_guid AND e.edition_guid=o.edition_guid JOIN ep_publications p ON p.tenant_guid=e.tenant_guid AND p.publication_guid=e.publication_guid LEFT JOIN ep_offline_devices d ON d.tenant_guid=o.tenant_guid AND d.platform_user_guid=o.platform_user_guid AND d.device_guid=o.device_guid LEFT JOIN ep_pages pg ON pg.tenant_guid=o.tenant_guid AND pg.edition_guid=o.edition_guid AND pg.page_number=1 LEFT JOIN ep_page_assets a ON a.tenant_guid=pg.tenant_guid AND a.page_guid=pg.page_guid AND a.asset_type="THUMB" WHERE o.tenant_guid=? AND o.platform_user_guid=? ORDER BY o.updated_at DESC LIMIT 100',[TenantData::tenantBin(),$uid]);foreach($rows as$r){$count++;$eg=Uuid::fromBinary($r['edition_guid']);$img=$this->assetUrlFromBinary($r['thumb_asset_guid']??null);$license=$this->guid($r['license_guid']??null);$expires=$r['expires_at']?date('d M Y · H:i',strtotime($r['expires_at'])):'—';$read=$license?'<a class="record-action" href="/offline-reader.html?license='.$this->e($license).'&page=1" data-offline-read="'.$this->e($license).'">Read offline</a>':'';$manage=$read.'<form method="post" action="/account/offline/'.$eg.'/delete" data-vault-remove-edition="'.$this->e($eg).'" data-confirm="Remove this encrypted offline edition from this account and device?">'.$this->csrf().'<button class="record-action danger">Remove offline copy</button></form>';$secondary=strtoupper((string)$r['status']).' · '.$this->formatBytes((int)$r['byte_size']).(!empty($r['device_label'])?' · '.$r['device_label']:'').' · Expires '.$expires;$html.=$this->accountCard('/edition/'.$this->e($r['slug']).'/page/1',$img,'Offline','ENCRYPTED OFFLINE EDITION',$r['publication_name'],date('d M Y',strtotime($r['edition_date'])).' · '.(int)$r['page_count'].' pages',$secondary,$manage,'edition-media');}}
            $html.='</div>';
        }
        if(!$count){$empty=['saved'=>['No saved articles yet','Open Smart Article while reading and save a story for later.'],'bookmarks'=>['No bookmarks yet','Bookmark a newspaper page to find it here quickly.'],'clips'=>['No clippings yet','Use Clip Mode in the Reader to save part of a newspaper page.'],'history'=>['No reading history yet','Open an edition and your latest reading position will appear here.'],'offline'=>['Nothing saved offline','Download an edition from the Reader to keep it available without internet.'],'notifications'=>['You’re all caught up','New edition and account updates will appear here.']][$type]??['Nothing here yet','Your library will appear here as you use ePaper SaaS.'];$html.='<section class="empty-state account-empty"><h2>'.$this->e($empty[0]).'</h2><p>'.$this->e($empty[1]).'</p><a class="btn primary" href="/">Open ePaper</a></section>';}
        View::layout($title,$html,['brand'=>$this->brandName(),'account'=>true]);
    }

    private function accountCard(string $url,?string $img,string $badge,string $eyebrow,string $title,string $meta,string $secondary,string $manage,string $mediaClass=''): string
    {
        return'<article class="library-card-wrap"><a class="library-media-card" href="'.$url.'"><div class="library-card-media '.$this->e($mediaClass).'">'.($img?'<img src="'.$this->e($img).'" alt="" loading="lazy" decoding="async">':'<div class="media-placeholder">'.$this->e($badge).'</div>').'<span class="media-badge">'.$this->e($badge).'</span></div><div class="library-card-body"><span class="eyebrow">'.$this->e($eyebrow).'</span><h3>'.$this->e($title).'</h3><p>'.$this->e($meta).'</p>'.($secondary!==''?'<small class="card-snippet">'.$this->e($secondary).'</small>':'').'</div></a>'.$this->recordMenu($manage).'</article>';
    }

    private function accountRemovableCount(string $uidBin,string $type): int
    {
        $tb=TenantData::tenantBin();$map=['saved'=>'ep_saved_articles','bookmarks'=>'ep_bookmarks','clips'=>'ep_clips','history'=>'ep_history','offline'=>'ep_offline_items','notifications'=>'ep_notifications'];if(!isset($map[$type]))return 0;return (int)Store::value('SELECT COUNT(*) FROM '.$map[$type].' WHERE tenant_guid=? AND platform_user_guid=?',[$tb,$uidBin]);
    }

    private function accountClear(array $u,string $pathType): never
    {
        $uid=Uuid::toBinary($u['user_guid']);$tb=TenantData::tenantBin();$typeMap=['saved-articles'=>'saved','bookmarks'=>'bookmarks','clips'=>'clips','history'=>'history','offline'=>'offline','notifications'=>'notifications'];if(!isset($typeMap[$pathType]))$this->adminError('Unsupported library clear action');$type=$typeMap[$pathType];$count=$this->accountRemovableCount($uid,$type);$clipPaths=[];if($type==='clips'){$rows=Store::all('SELECT storage_path FROM ep_clips WHERE tenant_guid=? AND platform_user_guid=?',[$tb,$uid]);foreach($rows as$r)$clipPaths[]=(string)($r['storage_path']??'');Store::exec('DELETE FROM ep_clips WHERE tenant_guid=? AND platform_user_guid=?',[$tb,$uid]);foreach($clipPaths as$storagePath){try{$this->cleanupClipFiles($storagePath);}catch(\Throwable$e){Audit::log('account.clip.file_cleanup.failed','account',null,'FAILED',['user_guid'=>$u['user_guid'],'storage_path'=>$storagePath,'message'=>$e->getMessage()]);}}}else{if($type==='offline')Store::exec('UPDATE ep_offline_licenses SET status="REVOKED",revoked_at=UTC_TIMESTAMP(6),updated_at=UTC_TIMESTAMP(6) WHERE tenant_guid=? AND platform_user_guid=? AND status<>"REVOKED"',[$tb,$uid]);$table=['saved'=>'ep_saved_articles','bookmarks'=>'ep_bookmarks','history'=>'ep_history','offline'=>'ep_offline_items','notifications'=>'ep_notifications'][$type];Store::exec('DELETE FROM '.$table.' WHERE tenant_guid=? AND platform_user_guid=?',[$tb,$uid]);}Audit::log('account.library.cleared','account',null,'SUCCESS',['user_guid'=>$u['user_guid'],'library_type'=>$type,'deleted_count'=>$count]);Http::redirect('/account/'.$pathType.'?cleared=1&count='.$count);
    }

    private function accountSavedAction(array $u,string $pageGuid,string $action): never
    {
        $tb=TenantData::tenantBin();$uid=Uuid::toBinary($u['user_guid']);$pg=Uuid::toBinary($pageGuid);if($action==='update'){Store::exec('UPDATE ep_saved_articles SET title=? WHERE tenant_guid=? AND platform_user_guid=? AND page_guid=?',[mb_substr(trim((string)($_POST['title']??'')),0,180),$tb,$uid,$pg]);Audit::log('saved_article.updated','page',$pageGuid);Http::redirect('/account/saved-articles?updated=1');}Store::exec('DELETE FROM ep_saved_articles WHERE tenant_guid=? AND platform_user_guid=? AND page_guid=?',[$tb,$uid,$pg]);Audit::log('saved_article.deleted','page',$pageGuid);Http::redirect('/account/saved-articles?updated=1');
    }

    private function accountBookmarkAction(array $u,string $targetGuid,string $action): never
    {
        $tb=TenantData::tenantBin();$uid=Uuid::toBinary($u['user_guid']);$target=Uuid::toBinary($targetGuid);if($action==='update'){Store::exec('UPDATE ep_bookmarks SET note=? WHERE tenant_guid=? AND platform_user_guid=? AND target_guid=?',[mb_substr(trim((string)($_POST['note']??'')),0,500),$tb,$uid,$target]);Audit::log('bookmark.updated','bookmark',$targetGuid);Http::redirect('/account/bookmarks?updated=1');}Store::exec('DELETE FROM ep_bookmarks WHERE tenant_guid=? AND platform_user_guid=? AND target_guid=?',[$tb,$uid,$target]);Audit::log('bookmark.deleted','bookmark',$targetGuid);Http::redirect('/account/bookmarks?updated=1');
    }

    private function accountClipAction(array $u,string $slug,string $action): never
    {
        $tb=TenantData::tenantBin();$uid=Uuid::toBinary($u['user_guid']);$row=Store::one('SELECT clip_guid FROM ep_clips WHERE tenant_guid=? AND platform_user_guid=? AND clip_slug=?',[$tb,$uid,$slug]);if(!$row)$this->notFound('Clipping unavailable');if($action==='update'){$title=trim((string)($_POST['title']??''));$visibility=strtoupper((string)($_POST['visibility']??'PRIVATE'));if($title===''||!in_array($visibility,['PRIVATE','PUBLIC'],true))$this->adminError('Clipping title and Private/Public visibility are required');Store::exec('UPDATE ep_clips SET title=?,visibility=?,updated_at=NOW(6) WHERE tenant_guid=? AND platform_user_guid=? AND clip_slug=?',[mb_substr($title,0,180),$visibility,$tb,$uid,$slug]);Audit::log('clip.updated','clip',Uuid::fromBinary($row['clip_guid']),'SUCCESS',['visibility'=>$visibility]);Http::redirect('/account/clips?updated=1');}$this->deleteOwnedClip($slug,$uid);Audit::log('clip.deleted','clip',Uuid::fromBinary($row['clip_guid']));Http::redirect('/account/clips?updated=1');
    }

    private function cleanupClipFiles(string $storagePath): void
    {
        if($storagePath==='')return;$root=dirname(__DIR__,2).'/storage/';$realRoot=rtrim(realpath($root)?:$root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR;$raw=$root.ltrim($storagePath,'/');$base=preg_replace('/\.webp$/i','',$raw)?:$raw;foreach(array_unique(array_merge([$raw],glob($base.'*')?:[])) as$f){$real=is_file($f)?(realpath($f)?:''):'';if($real!==''&&str_starts_with($real,$realRoot))@unlink($real);}
    }

    private function deleteOwnedClip(string $slug,string $uidBin): void
    {
        $clip=Store::one('SELECT clip_guid,storage_path FROM ep_clips WHERE tenant_guid=? AND platform_user_guid=? AND clip_slug=?',[TenantData::tenantBin(),$uidBin,$slug]);if(!$clip)return;Store::exec('DELETE FROM ep_clips WHERE tenant_guid=? AND platform_user_guid=? AND clip_slug=?',[TenantData::tenantBin(),$uidBin,$slug]);try{$this->cleanupClipFiles((string)$clip['storage_path']);}catch(\Throwable$e){Audit::log('clip.file_cleanup.failed','clip',Uuid::fromBinary($clip['clip_guid']),'FAILED',['message'=>$e->getMessage()]);}
    }

    private function accountHistoryDelete(array $u,string $editionGuid): never
    {
        Store::exec('DELETE FROM ep_history WHERE tenant_guid=? AND platform_user_guid=? AND edition_guid=?',[TenantData::tenantBin(),Uuid::toBinary($u['user_guid']),Uuid::toBinary($editionGuid)]);Audit::log('history.deleted','edition',$editionGuid);Http::redirect('/account/history?updated=1');
    }

    private function accountOfflineDelete(array $u,string $editionGuid): never
    {
        OfflineVault::revokeEdition($u,$editionGuid);Store::exec('DELETE FROM ep_offline_items WHERE tenant_guid=? AND platform_user_guid=? AND edition_guid=?',[TenantData::tenantBin(),Uuid::toBinary($u['user_guid']),Uuid::toBinary($editionGuid)]);Audit::log('offline.deleted','edition',$editionGuid);Http::redirect('/account/offline?updated=1');
    }

    private function accountNotificationAction(array $u,string $notificationGuid,string $action): never
    {
        $tb=TenantData::tenantBin();$uid=Uuid::toBinary($u['user_guid']);$ng=Uuid::toBinary($notificationGuid);$row=Store::one('SELECT notification_guid FROM ep_notifications WHERE tenant_guid=? AND platform_user_guid=? AND notification_guid=?',[$tb,$uid,$ng]);if(!$row)$this->notFound('Notification unavailable');if($action==='read')Store::exec('UPDATE ep_notifications SET status="READ" WHERE tenant_guid=? AND platform_user_guid=? AND notification_guid=?',[$tb,$uid,$ng]);else Store::exec('DELETE FROM ep_notifications WHERE tenant_guid=? AND platform_user_guid=? AND notification_guid=?',[$tb,$uid,$ng]);Audit::log('notification.'.$action,'notification',$notificationGuid);Http::redirect('/account/notifications?updated=1');
    }
}
